// Validate document input
const documentFile = $input.item.binary?.data;
const documentUrl = $input.item.json.document_url;
const options = $input.item.json.options || {};

if (!documentFile && !documentUrl) {
  throw new Error('No document file or URL provided');
}

// Supported document formats
const supportedFormats = ['pdf', 'png', 'jpg', 'jpeg', 'tiff', 'bmp', 'gif', 'webp'];
const fileName = documentFile?.fileName || documentUrl?.split('/').pop() || '';
const fileExtension = fileName.split('.').pop().toLowerCase();

if (!supportedFormats.includes(fileExtension)) {
  throw new Error(`Unsupported format: ${fileExtension}. Supported: ${supportedFormats.join(', ')}`);
}

const processingOptions = {
  request_id: `doc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  document_source: documentFile ? 'upload' : 'url',
  file_name: fileName,
  file_extension: fileExtension,
  extract_text: options.extract_text !== false,
  extract_tables: options.extract_tables !== false,
  extract_forms: options.extract_forms !== false,
  detect_language: options.detect_language !== false,
  classify_document: options.classify_document !== false,
  extract_entities: options.extract_entities !== false,
  providers: options.providers || ['tesseract', 'google_vision', 'azure_form_recognizer']
};

return {
  json: processingOptions,
  binary: documentFile ? { data: documentFile } : undefined
};

