parameters.functionCode:
// Aggregate all OCR and document intelligence results
const items = $input.all();

// Get base data
const baseData = items.find(item => item.json.request_id)?.json;

// Extract Tesseract OCR results
const tesseractResult = items.find(item => typeof item.json === 'string' && item.json.length > 50);
const tesseractText = tesseractResult?.json || '';

// Extract Google Vision OCR results
const googleVisionResult = items.find(item => item.json.fullTextAnnotation);
const googleVisionData = googleVisionResult ? {
  provider: 'google_vision',
  text: googleVisionResult.json.fullTextAnnotation.text,
  pages: googleVisionResult.json.fullTextAnnotation.pages?.length || 0,
  blocks: googleVisionResult.json.fullTextAnnotation.pages?.[0]?.blocks?.length || 0,
  confidence: googleVisionResult.json.fullTextAnnotation.pages?.[0]?.confidence || null,
  language: googleVisionResult.json.fullTextAnnotation.pages?.[0]?.property?.detectedLanguages?.[0]?.languageCode || 'unknown'
} : null;

// Extract Azure Form Recognizer results
const azureResult = items.find(item => item.json.status === 'succeeded' && item.json.analyzeResult);
const azureData = azureResult ? {
  provider: 'azure_form_recognizer',
  text: azureResult.json.analyzeResult.content,
  pages: azureResult.json.analyzeResult.pages?.length || 0,
  tables: azureResult.json.analyzeResult.tables?.map(table => ({
    row_count: table.rowCount,
    column_count: table.columnCount,
    cells: table.cells?.map(cell => ({
      row_index: cell.rowIndex,
      column_index: cell.columnIndex,
      content: cell.content,
      kind: cell.kind
    })) || []
  })) || [],
  key_value_pairs: azureResult.json.analyzeResult.keyValuePairs?.map(kvp => ({
    key: kvp.key?.content || '',
    value: kvp.value?.content || '',
    confidence: kvp.confidence
  })) || [],
  entities: azureResult.json.analyzeResult.entities?.map(ent => ({
    category: ent.category,
    content: ent.content,
    confidence: ent.confidence
  })) || []
} : null;

// Extract GPT-4 Vision classification
const gptVisionResult = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.document_type !== undefined;
    }
  } catch (e) {}
  return false;
});
const documentClassification = gptVisionResult ? (() => {
  const parsed = JSON.parse(gptVisionResult.json.choices[0].message.content);
  return {
    document_type: parsed.document_type,
    confidence: parsed.confidence,
    metadata: {
      title: parsed.title || null,
      date: parsed.date || null,
      sender: parsed.sender || null,
      recipient: parsed.recipient || null,
      summary: parsed.summary || null
    }
  };
})() : null;

// Choose best OCR text (longest and most complete)
const ocrTexts = [
  { provider: 'tesseract', text: tesseractText },
  { provider: 'google_vision', text: googleVisionData?.text || '' },
  { provider: 'azure', text: azureData?.text || '' }
].filter(item => item.text.length > 0);

const bestOCR = ocrTexts.reduce((best, current) => {
  return current.text.length > best.text.length ? current : best;
}, ocrTexts[0] || { provider: 'none', text: '' });

// Calculate text extraction confidence
function calculateTextSimilarity(text1, text2) {
  if (!text1 || !text2) return 0;
  const words1 = new Set(text1.toLowerCase().split(/\s+/));
  const words2 = new Set(text2.toLowerCase().split(/\s+/));
  const intersection = new Set([...words1].filter(x => words2.has(x)));
  const union = new Set([...words1, ...words2]);
  return intersection.size / union.size;
}

const ocrAgreement = ocrTexts.length >= 2 ?
  calculateTextSimilarity(ocrTexts[0].text, ocrTexts[1].text) : null;

// Build final result
const result = {
  request_id: baseData?.request_id,
  timestamp: baseData?.timestamp,
  document_info: {
    file_name: baseData?.file_name,
    format: baseData?.file_extension,
    source: baseData?.document_source
  },
  document_classification: documentClassification,
  text_extraction: {
    primary_text: bestOCR.text,
    primary_provider: bestOCR.provider,
    word_count: bestOCR.text.split(/\s+/).length,
    character_count: bestOCR.text.length,
    language: googleVisionData?.language || 'unknown',
    ocr_agreement_score: ocrAgreement ? parseFloat(ocrAgreement.toFixed(3)) : null
  },
  providers_results: {
    tesseract: tesseractText ? {
      text_preview: tesseractText.substring(0, 200),
      length: tesseractText.length
    } : null,
    google_vision: googleVisionData,
    azure_form_recognizer: azureData ? {
      pages: azureData.pages,
      tables_count: azureData.tables.length,
      key_value_pairs_count: azureData.key_value_pairs.length,
      entities_count: azureData.entities.length
    } : null
  },
  structured_data: {
    tables: azureData?.tables || [],
    key_value_pairs: azureData?.key_value_pairs || [],
    entities: azureData?.entities || []
  },
  metadata: {
    providers_used: ocrTexts.map(t => t.provider),
    processing_time_ms: Date.now() - new Date(baseData?.timestamp).getTime(),
    pages_processed: azureData?.pages || googleVisionData?.pages || 1
  }
};

return {
  json: result
};
